/* ═══ v6.1 책갈피 ═══
   브랜드가 '책'이면 마음에 든 문장을 꽂아 두는 건 필수 기능이다.
   저장 위치: localStorage `yomi_marks` = [{b,k,i,jp,ko,t}]  (b=책id, k=장, i=문장)  */
function mkAll(){ try{ return JSON.parse(localStorage.getItem("yomi_marks")||"[]"); }catch(e){ return []; } }
function mkSave(a){ try{ localStorage.setItem("yomi_marks", JSON.stringify(a.slice(-500))); }catch(e){} }
function mkHas(b,k,i){ return mkAll().some(m=>m.b===b&&m.k===k&&m.i===i); }
function mkToggle(e,i){
  e.stopPropagation();
  const b=rdBookCur, k=rdChapCur; if(!b) return;
  const s=b.chapters[k].s[i];
  let a=mkAll();
  const at=a.findIndex(m=>m.b===b.id&&m.k===k&&m.i===i);
  const el=e.currentTarget.closest(".rd-s");
  if(at>=0){ a.splice(at,1); el.classList.remove("mk"); toast("책갈피를 뺐어요"); }
  else{
    a.push({b:b.id,k:k,i:i,jp:rdPlain(s.jp),ko:s.ko,t:Date.now()});
    el.classList.add("mk"); toast("🔖 책갈피에 꽂았어요");
  }
  mkSave(a); mkSyncBtn();
}
function mkSyncBtn(){
  const el=$("rrMk"); if(!el) return;
  const n=mkAll().length;
  el.textContent = n ? `🔖 ${n}` : "🔖";
}
/** 책갈피 목록 화면 */
async function openMarks(){
  show("mkScreen"); window.scrollTo(0,0);
  const wrap=$("mkList");
  const a=mkAll().slice().reverse();
  if(!a.length){
    wrap.innerHTML=`<div class="mk-empty">아직 꽂아 둔 문장이 없어요.<br>
      책을 읽다가 마음에 드는 문장을 탭하고 <b>🔖</b> 를 누르면<br>여기에 모입니다.</div>`;
    $("mkCount").textContent=""; return;
  }
  $("mkCount").textContent=`${a.length}개`;
  await loadBooks();
  const byId={}; (BOOKS||[]).forEach(b=>byId[b.id]=b);
  wrap.innerHTML=a.map((m,idx)=>{
    const b=byId[m.b];
    const src=b ? `${b.title_ko} · ${m.k+1}장` : "(책을 찾을 수 없음)";
    return `<button class="mk-row" onclick="mkGo(${idx})">
      <span class="mi"><span class="mj">${m.jp}</span><span class="mko">${m.ko||""}</span>
        <span class="msrc">${src}</span></span>
      <span class="mdel" onclick="mkDel(event,${idx})">✕</span></button>`;
  }).join("");
}
function mkDel(e,idx){
  e.stopPropagation();
  const a=mkAll(); const rev=a.slice().reverse();
  const target=rev[idx];
  const at=a.findIndex(m=>m.b===target.b&&m.k===target.k&&m.i===target.i);
  if(at>=0){ a.splice(at,1); mkSave(a); }
  openMarks();
}
async function mkGo(idx){
  const m=mkAll().slice().reverse()[idx];
  await loadBooks();
  const b=(BOOKS||[]).find(x=>x.id===m.b);
  if(!b){ toast("책을 찾을 수 없어요"); return; }
  rdBookCur=b; openChapter(m.k);
  setTimeout(()=>{
    const el=$("rrBody").querySelectorAll(".rd-s")[m.i];
    if(el){ el.scrollIntoView({block:"center",behavior:"smooth"}); el.classList.add("open"); }
  },220);
}

